import { useState, useEffect } from 'react';
import { AppConfig } from '@/types';

export const useAppConfig = (defaultConfig = 'A-side') => {
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [songId, setSongId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Obtener parámetros de la URL
  const getParamsFromUrl = (): { configName: string; songId: string | null } => {
    const params = new URLSearchParams(window.location.search);
    const configName = params.get('config') || defaultConfig;
    const songId = params.get('song');
    return { configName, songId };
  };

  // Aplicar colores dinámicamente basados en la configuración
  const applyThemeColors = (colors: AppConfig['colors']) => {
    const root = document.documentElement;
    
    // Colores primarios, secundarios y de acento (solo H, para clases personalizadas)
    root.style.setProperty('--primary-h', colors.primary.toString());
    root.style.setProperty('--secondary-h', colors.secondary.toString());
    root.style.setProperty('--accent-h', colors.accent.toString());

    // Definir variables HSL completas para Tailwind
    root.style.setProperty('--primary', `${colors.primary} 70% 50%`);
    root.style.setProperty('--primary-foreground', `${colors.primary} 20% 95%`);
    
    root.style.setProperty('--secondary', `${colors.secondary} 60% 40%`);
    root.style.setProperty('--secondary-foreground', `${colors.secondary} 20% 95%`);
    
    root.style.setProperty('--accent', `${colors.accent} 80% 60%`);
    root.style.setProperty('--accent-foreground', `${colors.accent} 20% 10%`);
    
    root.style.setProperty('--muted', `${colors.primary} 20% 15%`);
    root.style.setProperty('--muted-foreground', colors.text.dimmed); 
    
    root.style.setProperty('--border', `${colors.primary} 30% 30%`);
    root.style.setProperty('--input', `${colors.primary} 20% 15%`);
    root.style.setProperty('--ring', `${colors.accent} 70% 60%`);
    
    root.style.setProperty('--background', `linear-gradient(135deg, ${colors.background.gradient[0]}, ${colors.background.gradient[1]})`);
    root.style.setProperty('--foreground', colors.text.primary); 
    
    root.style.setProperty('--card', `linear-gradient(135deg, ${colors.cards.gradient[0]}, ${colors.cards.gradient[1]})`);
    root.style.setProperty('--card-foreground', colors.text.primary); 
    
    root.style.setProperty('--popover', `${colors.primary} 25% 12%`);
    root.style.setProperty('--popover-foreground', colors.text.primary); 
    
    root.style.setProperty('--destructive', `0 62.8% 30.6%`); 
    root.style.setProperty('--destructive-foreground', `210 40% 98%`); 

    // Variables para los colores de texto específicos del JSON
    root.style.setProperty('--text-highlighted', colors.text.highlighted);
    root.style.setProperty('--text-dimmed', colors.text.dimmed);
    root.style.setProperty('--text-primary-custom', colors.text.primary);
    root.style.setProperty('--text-secondary-custom', colors.text.secondary);
    
    // También definir las variables sin sufijo -custom para compatibilidad con el CSS existente
    root.style.setProperty('--text-primary', colors.text.primary);
    root.style.setProperty('--text-secondary', colors.text.secondary);

    // Colores para subtítulos (calculados a partir del color base)
    const subtitleBase = colors.subtitles.base;
    root.style.setProperty('--subtitles-base-h', subtitleBase.toString()); // Mantener para clases personalizadas
    root.style.setProperty('--subtitle-highlighted', `hsl(${subtitleBase}, 80%, 90%)`);
    root.style.setProperty('--subtitle-dimmed', `hsl(${subtitleBase}, 60%, 50%)`);
    root.style.setProperty('--subtitle-bg', `linear-gradient(135deg, hsl(${subtitleBase}, 30%, 15%), hsl(${subtitleBase}, 20%, 8%))`);
    
    // Radio para bordes redondeados (duplicado)
    root.style.setProperty('--radius', '1.5rem');
    
    // Aplicar estilos de neon y efectos visuales
    applyNeonEffects(colors);
  };

  // Aplicar efectos de neon y brillo basados en los colores
  const applyNeonEffects = (colors: AppConfig['colors']) => {
    const root = document.documentElement;
    
    // Efectos de neon para botones y elementos interactivos
    root.style.setProperty('--neon-primary', `0 0 10px hsl(${colors.primary}, 70%, 50%), 0 0 20px hsl(${colors.primary}, 70%, 50%)`);
    root.style.setProperty('--neon-secondary', `0 0 10px hsl(${colors.secondary}, 60%, 40%), 0 0 20px hsl(${colors.secondary}, 60%, 40%)`);
    root.style.setProperty('--neon-accent', `0 0 10px hsl(${colors.accent}, 80%, 60%), 0 0 20px hsl(${colors.accent}, 80%, 60%)`);
    
    // Efectos de texto neon
    root.style.setProperty('--text-neon-primary', `0 0 5px hsl(${colors.primary}, 70%, 50%), 0 0 10px hsl(${colors.primary}, 70%, 50%)`);
    root.style.setProperty('--text-neon-secondary', `0 0 5px hsl(${colors.secondary}, 60%, 40%), 0 0 10px hsl(${colors.secondary}, 60%, 40%)`);
  };

  // Cargar la configuración
  useEffect(() => {
    const loadConfig = async () => {
      try {
        const { configName, songId: urlSongId } = getParamsFromUrl();
        setSongId(urlSongId);

        const response = await fetch(configName === 'my-side' ? `/my-side.json?v=${Date.now()}` : `/${configName}.json?v=${Date.now()}`);
        
        if (!response.ok) {
          throw new Error(`Error al cargar configuración: ${response.status}`);
        }
        
        const configData: AppConfig = await response.json();
        setConfig(configData);

        // Cargar y aplicar el tema dinámicamente
        if (configData.theme) {
          const themeResponse = await fetch(`/theme-${configData.theme}.json?v=${Date.now()}`);
          if (!themeResponse.ok) {
            throw new Error(`Error al cargar el tema: ${themeResponse.status}`);
          }
          const themeConfig = await themeResponse.json();
          applyThemeColors(themeConfig);
        }
        
       // Guardar el lado visitado en localStorage
       const storedSides = JSON.parse(localStorage.getItem('unlocked_sides') || '[]');
       if (!storedSides.includes(configName)) {
         storedSides.push(configName);
         localStorage.setItem('unlocked_sides', JSON.stringify(storedSides));
       }

     } catch (error) {
       console.error('Error loading config:', error);
       setError(error instanceof Error ? error.message : 'Error desconocido');
     } finally {
        setIsLoading(false);
      }
    };

    loadConfig();
  }, []);

  // Función para cambiar de configuración
  const switchConfig = (targetConfig: string) => {
    // Construir nueva URL con el parámetro de configuración
    const newUrl = new URL(window.location.origin);
    newUrl.searchParams.set('config', targetConfig);
    // No incluir el parámetro 'song' para cargar la playlist completa
    
    // Recargar la página con la nueva configuración
    window.location.href = newUrl.toString();
  };

  return {
    config,
    songId,
    isLoading,
    error,
    switchConfig,
  };
};


