 @tailwind base;
@tailwind components;
@tailwind utilities;

/* Retro Beat Player - Sistema de Temas Dinámicos */
/* Los colores se gestionan a través de variables CSS dinámicas */

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground;
    background: var(--background);
    background-attachment: fixed;
    font-family: 'Courier New', monospace;
    overflow-x: hidden;
    min-height: 100vh;
  }
}

/* Custom Components - Estructura con colores dinámicos */
@layer components {
  .neon-border {
    border: 2px solid hsl(var(--primary-h), 70%, 50%);
    box-shadow: var(--neon-primary), inset 0 0 10px hsl(var(--primary-h), 30%, 20%);
  }
  
  .neon-text {
    text-shadow: var(--text-neon-primary);
  }
  
  .neon-text-secondary {
    text-shadow: var(--text-neon-secondary);
  }
  
  .glass-effect {
    background: var(--card);
    backdrop-filter: blur(10px);
    border: 1px solid hsl(var(--primary-h), 30%, 30%);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    padding: 1.5rem;
  }
  
  .card-glow {
    box-shadow: var(--neon-primary), var(--neon-secondary), var(--neon-accent);
    border-radius: var(--radius);
  }
  
  .albumart-glow {
    box-shadow: 
      0 0 25px hsla(var(--primary-h), 80%, 60%, 0.4),
      0 0 50px hsla(var(--primary-h), 70%, 50%, 0.3),
      0 0 75px hsla(var(--primary-h), 60%, 40%, 0.2);
    border-radius: var(--radius);
    border: 3px solid hsla(var(--primary-h), 70%, 50%, 0.7);
  }
  
  .musicplayer-glow {
    box-shadow: 
      0 0 25px hsla(var(--secondary-h), 80%, 60%, 0.4),
      0 0 50px hsla(var(--secondary-h), 70%, 50%, 0.3),
      0 0 75px hsla(var(--secondary-h), 60%, 40%, 0.2);
    border-radius: var(--radius);
    border: 3px solid hsla(var(--secondary-h), 60%, 40%, 0.7);
  }
  
  .playlist-glow {
    box-shadow: 
      0 0 25px hsla(var(--accent-h), 80%, 60%, 0.4),
      0 0 50px hsla(var(--accent-h), 70%, 50%, 0.3),
      0 0 75px hsla(var(--accent-h), 60%, 40%, 0.2);
    border-radius: var(--radius);
    border: 3px solid hsla(var(--accent-h), 70%, 50%, 0.7);
  }
  
  .exclusions-glow {
    box-shadow: 
      0 0 25px hsla(var(--primary-h), 60%, 40%, 0.4),
      0 0 50px hsla(var(--primary-h), 50%, 30%, 0.3),
      0 0 75px hsla(var(--primary-h), 40%, 20%, 0.2);
    border-radius: var(--radius);
    border: 3px solid hsla(var(--primary-h), 50%, 30%, 0.7);
  }
  
  .crt-glow {
    box-shadow: 
      0 0 30px hsl(var(--subtitles-base-h), 80%, 60%),
      0 0 60px hsl(var(--subtitles-base-h), 60%, 40%),
      0 0 90px hsl(var(--subtitles-base-h), 40%, 20%),
      inset 0 0 30px rgba(0, 0, 0, 0.5);
    border: 3px solid hsl(var(--subtitles-base-h), 60%, 40%);
    border-radius: var(--radius);
  }
  
  .crt-glow-animated {
    animation: crt-pulse 3s ease-in-out infinite alternate, crt-flicker 0.1s ease-in-out infinite alternate;
  }
  
  @keyframes crt-pulse {
    0% {
      box-shadow: 
        0 0 30px hsl(var(--subtitles-base-h), 80%, 60%),
        0 0 60px hsl(var(--subtitles-base-h), 60%, 40%),
        0 0 90px hsl(var(--subtitles-base-h), 40%, 20%),
        inset 0 0 30px rgba(0, 0, 0, 0.5);
    }
    100% {
      box-shadow: 
        0 0 40px hsl(var(--subtitles-base-h), 90%, 70%),
        0 0 80px hsl(var(--subtitles-base-h), 70%, 50%),
        0 0 120px hsl(var(--subtitles-base-h), 50%, 30%),
        inset 0 0 40px rgba(0, 0, 0, 0.6);
    }
  }
  
  @keyframes crt-flicker {
    0%, 100% {
      opacity: 1;
    }
    50% {
      opacity: 0.95;
    }
  }
  
  .synthwave-button {
    background: linear-gradient(135deg, hsl(var(--primary-h), 40%, 20%), hsl(var(--secondary-h), 30%, 15%));
    color: var(--text-primary-custom);
    border: 1px solid hsl(var(--primary-h), 30%, 30%);
    padding: 0.75rem 1.5rem;
    border-radius: var(--radius);
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    transition: all 0.3s ease;
    box-shadow: 0 0 5px hsl(var(--primary-h), 50%, 30%, 0.5);
    font-size: 1.1rem;
  }
  
  .synthwave-button:hover {
    transform: translateY(-2px);
    background: linear-gradient(135deg, hsl(var(--primary-h), 70%, 50%), hsl(var(--accent-h), 80%, 60%));
    color: hsl(var(--primary-h), 20%, 95%);
    box-shadow: var(--neon-primary), 0 0 30px hsl(var(--primary-h), 70%, 50%);
  }
  
  .synthwave-button-secondary {
    background: linear-gradient(135deg, hsl(var(--secondary-h), 30%, 15%), hsl(var(--accent-h), 20%, 10%));
    color: var(--text-secondary-custom);
    border: 1px solid hsl(var(--secondary-h), 20%, 20%);
    padding: 0.75rem 1.5rem;
    border-radius: var(--radius);
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    transition: all 0.3s ease;
    box-shadow: 0 0 5px hsl(var(--secondary-h), 40%, 25%, 0.5);
    font-size: 1.1rem;
  }
  
  .synthwave-button-secondary:hover {
    transform: translateY(-2px);
    background: linear-gradient(135deg, hsl(var(--secondary-h), 60%, 40%), hsl(var(--primary-h), 70%, 50%));
    color: hsl(var(--secondary-h), 20%, 95%);
    box-shadow: var(--neon-secondary), 0 0 30px hsl(var(--secondary-h), 60%, 40%);
  }
  
  .synthwave-button-gradient {
    background: linear-gradient(135deg, hsl(var(--primary-h), 50%, 30%), hsl(var(--secondary-h), 40%, 25%));
    color: var(--text-highlighted);
    border: none;
    padding: 0.75rem 1.5rem;
    border-radius: var(--radius);
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    transition: all 0.3s ease;
    box-shadow: 0 0 10px hsl(var(--primary-h), 50%, 30%, 0.5), 0 0 20px hsl(var(--secondary-h), 40%, 25%, 0.3);
    font-size: 1.1rem;
  }
  
  .synthwave-button-gradient:hover {
    transform: translateY(-2px);
    background: linear-gradient(135deg, hsl(var(--primary-h), 70%, 50%), hsl(var(--accent-h), 80%, 60%));
    color: hsl(var(--primary-h), 20%, 95%);
    box-shadow: var(--neon-primary), 0 0 30px hsl(var(--primary-h), 70%, 50%);
  }
.play-button-active {
    transform: translateY(-2px);
    background: linear-gradient(135deg, hsl(var(--primary-h), 70%, 50%), hsl(var(--accent-h), 80%, 60%));
    color: hsl(var(--primary-h), 20%, 95%);
    box-shadow: var(--neon-primary), 0 0 30px hsl(var(--primary-h), 70%, 50%);
  }

  /* Fix for blurry text on active song in playlist */
  .neon-text {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }
  
  .lyrics-display {
    background: var(--subtitle-bg);
    border-radius: var(--radius);
    padding: 1rem;
    font-family: 'Courier New', monospace;
    position: relative;
    height: 140px;
    overflow: hidden;
    border: 2px solid hsl(var(--subtitles-base-h), 60%, 40%);
    box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.5), 0 0 20px hsl(var(--subtitles-base-h), 40%, 30%);
  }

  .lyrics-content {
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    position: relative;
    z-index: 2;
  }
.lyric-line {
    text-align: center;
    transition: all 0.3s ease;
    font-family: 'Courier New', monospace;
  }

  .lyric-prev {
    color: var(--subtitle-dimmed);
    opacity: 0.6;
    font-size: 0.875rem;
    text-shadow: 0 0 5px hsl(var(--subtitles-base-h), 60%, 40%);
  }

  .lyric-current {
    color: var(--subtitle-highlighted);
    font-size: 1.125rem;
    font-weight: bold;
    margin: 0.5rem 0;
    text-shadow: 0 0 10px hsl(var(--subtitles-base-h), 80%, 70%), 0 0 20px hsl(var(--subtitles-base-h), 60%, 50%);
  }

  .lyric-next {
    color: var(--subtitle-dimmed);
    opacity: 0.8;
    font-size: 0.875rem;
    text-shadow: 0 0 5px hsl(var(--subtitles-base-h), 60%, 40%);
  }

  .lyric-link {
    color: var(--subtitle-highlighted);
    text-decoration: underline;
    text-decoration-thickness: 2px;
    text-underline-offset: 2px;
    transition: all 0.3s ease;
    cursor: pointer;
    font-weight: bold;
    text-shadow: 0 0 5px hsl(var(--subtitles-base-h), 80%, 70%);
  }

  .lyric-link:hover {
    color: var(--subtitle-highlighted);
    text-shadow: 0 0 10px hsl(var(--subtitles-base-h), 80%, 70%), 0 0 20px hsl(var(--subtitles-base-h), 60%, 50%);
  }

  .scan-lines {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: repeating-linear-gradient(
      0deg,
      transparent 0px,
      transparent 2px,
      hsl(var(--subtitles-base-h), 80%, 90%, 0.1) 2px,
      hsl(var(--subtitles-base-h), 80%, 90%, 0.1) 4px
    );
    animation: scan-move 3s linear infinite;
    pointer-events: none;
  }

  @keyframes scan-move {
    0% { transform: translateY(-100%); opacity: 0; }
    50% { opacity: 1; }
    100% { transform: translateY(100%); opacity: 0; }
  }
  
  .pulse-glow {
    animation: pulse-glow 2s ease-in-out infinite alternate;
  }
  
  .gradient-text-primary {
    background: linear-gradient(135deg, hsl(var(--primary-h), 70%, 60%), hsl(var(--primary-h), 80%, 80%));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  
  .gradient-text-secondary {
    background: linear-gradient(135deg, hsl(var(--secondary-h), 60%, 50%), hsl(var(--secondary-h), 70%, 70%));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  
  .gradient-text-accent {
    background: linear-gradient(135deg, hsl(var(--accent-h), 80%, 60%), hsl(var(--accent-h), 90%, 80%));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  
  .hover-glow:hover {
    box-shadow: var(--neon-primary);
    transform: translateY(-2px);
  }
  
  .text-highlighted {
    color: var(--text-highlighted);
    text-shadow: 0 0 5px var(--text-highlighted);
  }
  
  .text-dimmed {
    color: var(--text-dimmed);
  }
  
  .text-primary-custom {
    color: var(--text-primary);
  }
  
  .text-secondary-custom {
    color: var(--text-secondary);
  }
}

@layer utilities {
  .animate-slide-down {
    animation: slide-down 0.3s ease-out forwards;
  }
}

@keyframes slide-down {
  from {
    transform: translateY(-100%);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes pulse-glow {
  0% {
    box-shadow: 0 0 10px hsl(var(--primary-h), 70%, 50%);
  }
  100% {
    box-shadow: 0 0 30px hsl(var(--primary-h), 70%, 50%), 0 0 60px hsl(var(--primary-h), 70%, 50%);
  }
}

@media (max-width: 768px) {
  .playlist-control-button {
    padding-left: 0.5rem;
    padding-right: 0.5rem;
  }
}


