        return;
    }
    let nextIndex;
    if (isShuffled) {
        const nextShuffleIndex = currentShuffleIndex + 1;
        if (nextShuffleIndex < shuffledIndices.length) {
            setCurrentShuffleIndex(nextShuffleIndex);
